def _cov_query(c, fn, p, cap):
    buf = (ctypes.c_double * cap)()
    n = fn(c, p, buf, cap)
    if n < 0:
        raise AraelError(
            n, (_f.graph_cov_error(c) or b"").decode())
    return buf


def _shape_1(buf):
    return float(buf[0])


def _shape_2(buf):
    return _m.matrix2d.from_elements(buf[0], buf[1], buf[2], buf[3])


def _shape_3(buf):
    return _m.matrix3d.from_elements(*[buf[i] for i in range(9)])


def _shape_n(buf, n):
    return tuple(tuple(buf[r * n + c] for c in range(n)) for r in range(n))


class Covariance:
    """An assembled covariance, OWNED: released on garbage
    collection (free() to force it), independent of later assemblies.
    Per-entity queries (marginal/conditional by param count: 1 ->
    float, 2/3 -> matrix2d/3d, larger -> row-major tuples). Entity
    arguments must come from the live model."""

    __slots__ = ("_h",)

    def __init__(self, h):
        self._h = h

    def free(self):
        if self._h:
            _f.graph_cov_free(self._h)
            self._h = None

    def __del__(self):
        try:
            self.free()
        except Exception:
            pass

    def marginal(self, e):
        """The entity's marginal covariance block."""
        if isinstance(e, Pose2):
            return (_shape_3)(_cov_query(self._h, _f.graph_pose2_marginal_cov, e._p, 9))
        raise TypeError("no marginal for %r" % (e,))

    def conditional(self, e):
        """Conditional covariance (all other parameters fixed)."""
        if isinstance(e, Pose2):
            return (_shape_3)(_cov_query(self._h, _f.graph_pose2_conditional_cov, e._p, 9))
        raise TypeError("no conditional for %r" % (e,))

    def std_dev(self, e):
        """Per-parameter standard deviations (every CovMode, incl.
        TriDiagonal)."""
        if isinstance(e, Pose2):
            return list(_cov_query(self._h, _f.graph_pose2_std_dev, e._p, 3))
        raise TypeError("no std_dev for %r" % (e,))
    def _cross_pose2_pose2(self, a, b):
        buf = (ctypes.c_double * 9)()
        rows = _f.graph_pose2_pose2_cross_cov(self._h, a._p, b._p, buf, 9)
        if rows < 0:
            raise AraelError(
                rows, (_f.graph_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 3 + c] for c in range(3))
                     for r in range(rows))

    def cross(self, a, b):
        """Row-major cross-covariance block between two entities."""
        if isinstance(a, Pose2) and isinstance(b, Pose2):
            return self._cross_pose2_pose2(a, b)
        raise TypeError("no cross-covariance for %r x %r" % (a, b))


class GraphPosesVec:
    """View of `poses` (vec of Pose2); element wrappers re-resolve
    their pointer by key on every access, so growing the collection
    cannot leave them dangling. Mutating while iterating is undefined."""

    __slots__ = ("_p",)

    def __init__(self, p):
        self._p = p

    def __len__(self):
        return _f.graph_poses_len(self._p)

    def reserve(self, additional):
        _f.graph_poses_reserve(self._p, additional)

    def __getitem__(self, i):
        if isinstance(i, Pose2Ref):
            return Pose2(lambda r=i.raw: _f.graph_poses_get(self._p, r))
        n = len(self)
        if i < 0:
            i += n
        if not 0 <= i < n:
            raise IndexError(i)
        return Pose2(lambda i=i: _f.graph_poses_at(self._p, i))

    def __iter__(self):
        for i in range(len(self)):
            yield Pose2(lambda i=i: _f.graph_poses_at(self._p, i))

    def clear(self):
        _f.graph_poses_clear(self._p)

    def truncate(self, n):
        _f.graph_poses_truncate(self._p, n)

    def push(self):
        _f.graph_poses_push(self._p)
        return self[self.ref_at(len(self) - 1)]

    def pop(self):
        """Drops the last element; False when already empty."""
        return _f.graph_poses_pop(self._p)

    def get(self, r):
        return Pose2(lambda k=_raw(r): _f.graph_poses_get(self._p, k))

    def __contains__(self, r):
        return _f.graph_poses_contains(self._p, _raw(r))

    def try_get(self, r):
        """The element, or None for a stale or foreign ref."""
        p = _f.graph_poses_try_get(self._p, _raw(r))
        return Pose2(lambda k=_raw(r): _f.graph_poses_get(self._p, k)) if p else None

    def ref_at(self, i):
        return Pose2Ref(_f.graph_poses_ref_at(self._p, i))

    def first_ref(self):
        """Ref of the first element; null when empty."""
        return Pose2Ref(_f.graph_poses_first_ref(self._p))

    def last_ref(self):
        """Ref of the last element; null when empty."""
        return Pose2Ref(_f.graph_poses_last_ref(self._p))


