class Graph:
    """The model. Owns the underlying Rust instance; free() (or GC)
    releases it. One model, one thread."""

    def __init__(self):
        load()
        self._p = _f.graph_new()

    def free(self):
        if self._p:
            _f.graph_free(self._p)
            self._p = None

    def __del__(self):
        try:
            self.free()
        except Exception:
            pass

    def _solved(self, code, res):
        if code < 0:
            raise AraelError(code, _err(self._p),
                             res if res._detail else None)
        return res

    def solve_dense(self, cfg=None):
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.graph_solve_dense(self._p, ctypes.byref(cfg),
                                     ctypes.byref(r)), r)

    def solve_sparse(self, cfg=None, opts=None):
        """Sparse solve; `opts` (a SparseOptions) selects the
        backend's route, None means the defaults."""
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.graph_solve_sparse(
                self._p, ctypes.byref(cfg),
                ctypes.byref(opts) if opts is not None else None,
                ctypes.byref(r)), r)

    def solve_band(self, kd, cfg=None):
        """Band Cholesky solve; kd is the half-bandwidth in scalar
        parameters."""
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.graph_solve_band(self._p, kd, ctypes.byref(cfg),
                                    ctypes.byref(r)), r)

    def assemble_covariance(self, mode=CovMode.ALL_MARGINALS):
        c = ctypes.c_void_p()
        code = _f.graph_assemble_covariance(self._p, int(mode),
                                                ctypes.byref(c))
        if code != 0:
            raise AraelError(code, _err(self._p))
        return Covariance(c)

    def cost(self):
        """Total cost at the current parameter values (no solve)."""
        return _f.graph_cost(self._p)

    def validate(self):
        """Empty string when the model is clean, the diagnostic text
        otherwise."""
        return _f.graph_validate(self._p).decode()

    def last_error(self):
        return _err(self._p)

    @property
    def poses(self):
        return GraphPosesVec(self._p)

    @property
    def edges(self):
        return GraphEdgesVec(self._p)

    @property
    def prior(self):
        """The `Prior`, or None while absent (make_prior() creates)."""
        if not _f.graph_prior(self._p):
            return None
        return Prior(lambda: _f.graph_prior(self._p))

    def make_prior(self):
        _f.graph_make_prior(self._p)
        return Prior(lambda: _f.graph_prior(self._p))

    def clear_prior(self):
        _f.graph_clear_prior(self._p)

